namespace sv_fb71ffccc85f48f2932ec1d775999461.Services;

/// <summary>
/// Scoped service that holds the currently selected warehouse for a single circuit.
/// Because it is registered as Scoped, each Blazor Server circuit (user session)
/// gets its own independent instance.
/// </summary>
public class WarehouseStateService : IDisposable
{
    private string _selectedWarehouseId = "WH-001";

    public string SelectedWarehouseId
    {
        get => _selectedWarehouseId;
        set
        {
            if (_selectedWarehouseId == value) return;
            _selectedWarehouseId = value;
            NotifyStateChanged();
        }
    }

    public string SelectedWarehouseName =>
        AvailableWarehouses.FirstOrDefault(w => w.Id == _selectedWarehouseId)?.Name ?? "Unknown";

    public IReadOnlyList<Warehouse> AvailableWarehouses { get; } = new List<Warehouse>
    {
        new("WH-001", "Warehouse A - Main Distribution"),
        new("WH-002", "Warehouse B - East Regional"),
        new("WH-003", "Warehouse C - West Regional"),
        new("WH-004", "Warehouse D - Cold Storage"),
    };

    public event Action? OnChange;

    private void NotifyStateChanged() => OnChange?.Invoke();

    public void Dispose() => OnChange = null;
}

public record Warehouse(string Id, string Name);

namespace sv_fb71ffccc85f48f2932ec1d775999461.Services;

/// <summary>
/// Scoped service that provides low-stock alert counts and coordinates polling
/// notifications across all subscribed components in a single circuit.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly Random _random = new();
    private int _lastAlertCount;

    public int LastAlertCount => _lastAlertCount;

    /// <summary>
    /// Simulates a database query returning the count of items below minimum stock levels.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Fetches new alert data and notifies all subscribers.
    /// Called by the polling component; all other subscribers react to the event.
    /// </summary>
    public async Task RefreshAlertCountAsync(string warehouseId)
    {
        _lastAlertCount = await GetLowStockCountAsync(warehouseId);
        NotifySubscribers();
    }

    /// <summary>
    /// Fired whenever new alert data is available.
    /// Any component can subscribe to be notified of updates.
    /// </summary>
    public event Action? OnAlertCountChanged;

    private void NotifySubscribers() => OnAlertCountChanged?.Invoke();

    public void Dispose() => OnAlertCountChanged = null;
}

