@using sv_fb71ffccc85f48f2932ec1d775999461.Services
@inject WarehouseStateService WarehouseState
@implements IDisposable
@rendermode InteractiveServer

<div class="warehouse-selector">
    <label class="form-label text-white mb-1 small">Current Warehouse</label>
    <select class="form-select form-select-sm" @bind="SelectedId">
        @foreach (var wh in WarehouseState.AvailableWarehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    private string SelectedId
    {
        get => WarehouseState.SelectedWarehouseId;
        set => WarehouseState.SelectedWarehouseId = value;
    }

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += HandleStateChanged;
    }

    private void HandleStateChanged() => InvokeAsync(StateHasChanged);

    public void Dispose()
    {
        WarehouseState.OnChange -= HandleStateChanged;
    }
}

@using sv_fb71ffccc85f48f2932ec1d775999461.Services
@inject InventoryAlertService AlertService
@inject WarehouseStateService WarehouseState
@implements IDisposable
@rendermode InteractiveServer

<span class="badge rounded-pill @BadgeClass">@AlertCount</span>

@code {
    private int AlertCount => AlertService.LastAlertCount;

    private string BadgeClass => AlertCount switch
    {
        0 => "bg-success",
        <= 5 => "bg-warning text-dark",
        _ => "bg-danger"
    };

    protected override void OnInitialized()
    {
        AlertService.OnAlertCountChanged += HandleAlertChanged;
        WarehouseState.OnChange += HandleWarehouseChanged;
    }

    private void HandleAlertChanged() => InvokeAsync(StateHasChanged);

    private async void HandleWarehouseChanged()
    {
        await AlertService.RefreshAlertCountAsync(WarehouseState.SelectedWarehouseId);
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
