var builder = WebApplication.CreateBuilder(args);

// Add services to the container.
builder.Services.AddRazorComponents()
    .AddInteractiveServerComponents();

// Scoped = one instance per circuit (per user session).
// Each browser tab / user gets independent warehouse state and alert counts.
builder.Services.AddScoped<WarehouseStateService>();
builder.Services.AddScoped<InventoryAlertService>();

var app = builder.Build();

