@page "/dashboard"
@using sv_fb71ffccc85f48f2932ec1d775999461.Services
@using sv_fb71ffccc85f48f2932ec1d775999461.Components.Shared
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Dashboard - @WarehouseState.SelectedWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Current Warehouse</h5>
                <p class="card-text fs-4">@WarehouseState.SelectedWarehouseName</p>
                <p class="text-muted">ID: @WarehouseState.SelectedWarehouseId</p>
            </div>
        </div>
    </div>
    <div class="col-md-6">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Low Stock Alerts</h5>
                <div class="d-flex align-items-center gap-3">
                    <span class="fs-1">@AlertService.LastAlertCount</span>
                    <AlertBadge />
                </div>
                <p class="text-muted mt-2">
                    @if (_isPolling)
                    {
                        <span class="text-success">● Polling active (every 10s)</span>
                    }
                    else
                    {
                        <span class="text-secondary">○ Polling stopped</span>
                    }
                </p>
            </div>
        </div>
    </div>
</div>

<div class="row">
    <div class="col-12">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Recent Activity</h5>
                <ul class="list-group list-group-flush">
                    @foreach (var entry in _activityLog.TakeLast(10).Reverse())
                    {
                        <li class="list-group-item">@entry</li>
                    }
                </ul>
            </div>
        </div>
    </div>
</div>

@code {
    private CancellationTokenSource? _pollingCts;
    private bool _isPolling;
    private readonly List<string> _activityLog = new();

    protected override async Task OnInitializedAsync()
    {
        WarehouseState.OnChange += HandleWarehouseChanged;
        AlertService.OnAlertCountChanged += HandleAlertChanged;

        // Initial fetch
        await AlertService.RefreshAlertCountAsync(WarehouseState.SelectedWarehouseId);
        _activityLog.Add($"{DateTime.Now:HH:mm:ss} - Initial load: {AlertService.LastAlertCount} low-stock items");

        StartPolling();
    }

    private void StartPolling()
    {
        _pollingCts = new CancellationTokenSource();
        _isPolling = true;
        _ = PollAsync(_pollingCts.Token);
    }

    private void StopPolling()
    {
        _pollingCts?.Cancel();
        _pollingCts?.Dispose();
        _pollingCts = null;
        _isPolling = false;
    }

    private async Task PollAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(10), ct);
                await AlertService.RefreshAlertCountAsync(WarehouseState.SelectedWarehouseId);
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    private async void HandleWarehouseChanged()
    {
        _activityLog.Add($"{DateTime.Now:HH:mm:ss} - Switched to {WarehouseState.SelectedWarehouseName}");
        await AlertService.RefreshAlertCountAsync(WarehouseState.SelectedWarehouseId);
        await InvokeAsync(StateHasChanged);
    }

    private void HandleAlertChanged()
    {
        _activityLog.Add($"{DateTime.Now:HH:mm:ss} - Alert update: {AlertService.LastAlertCount} low-stock items");
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        StopPolling();
        WarehouseState.OnChange -= HandleWarehouseChanged;
        AlertService.OnAlertCountChanged -= HandleAlertChanged;
    }
}

